import java.util.*;

class Solution {
  public int[] minReverseOperations(int n, int p, int[] banned, int k) {
    boolean[] ban = new boolean[n];
    for (int x : banned) ban[x] = true;
    TreeSet<Integer>[] s = new TreeSet[2];
    for (int i = 0; i < 2; i++) s[i] = new TreeSet<>();
    for (int i = 0; i < n; i++) if (!ban[i] && i != p) s[i & 1].add(i);
    int[] d = new int[n];
    Arrays.fill(d, -1);
    d[p] = 0;
    ArrayDeque<Integer> q = new ArrayDeque<>();
    q.add(p);
    while (!q.isEmpty()) {
      int x = q.remove();
      int lo = Math.max(0, x - k + 1), hi = Math.min(x, n - k);
      int l = 2 * lo + k - 1 - x, r = 2 * hi + k - 1 - x;
      TreeSet<Integer> t = s[(k - 1 - x) & 1];
      for (Integer y = t.ceiling(l); y != null && y <= r; ) {
        t.remove(y);
        d[y] = d[x] + 1;
        q.add(y);
        y = t.ceiling(y);
      }
    }
    return d;
  }
}
